"""Synthetic catalogue deletion: cancel, mandatory replacement, mobile confirmation, cross-session persistence."""
import asyncio
from playwright.async_api import async_playwright
H='http://127.0.0.1:8010'
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=await b.new_page(viewport={'width':1400,'height':1000});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));await p.route('https://**/*',lambda r:r.abort());await p.goto(H+'/login');await p.locator('input[type=text]').first.fill('TESTADMIN');await p.locator('input[type=password]').fill('PruebaSegura123!');await p.get_by_role('button',name='Iniciar Sesión',exact=True).click();await p.locator('nav.sidebar').wait_for()
  async def api(path,method='GET',d=None):return await p.evaluate('(v)=>SICIPCentral.api(v.path,{method:v.method,...(v.d?{body:JSON.stringify(v.d)}:{})})',dict(path=path,method=method,d=d))
  for clave in ['A','B','C']:await api('/api/admin/unidades','POST',dict(clave=clave,nombre='Unidad '+clave,activo=True,version=0))
  await api('/api/admin/unidades/asignar','POST',dict(unidad='A',matriculas=['TESTUSER']));await p.goto(H+'/admin');await p.get_by_role('button',name='Nombres de las unidades',exact=True).click();await p.locator('[data-unit-list]').wait_for();row=p.locator('[data-unit-list] tr').filter(has_text='Unidad A');await row.get_by_role('button',name='Eliminar',exact=True).click();d=p.locator('dialog[open]');await d.get_by_text('Tiene 1 trabajador(es).',exact=False).wait_for();await d.get_by_role('button',name='Cancelar',exact=True).click();assert any(u['clave']=='A' for u in await api('/api/unidades/catalogo'));await row.get_by_role('button',name='Eliminar',exact=True).click();d=p.locator('dialog[open]');await d.get_by_role('button',name='Confirmar eliminación').click();assert await d.count()==1 and not await d.locator('form').evaluate('(f)=>f.checkValidity()');await d.locator('select').select_option('B');await p.set_viewport_size(dict(width=390,height=844));assert await d.evaluate('(d)=>d.scrollWidth<=d.clientWidth+1');await d.get_by_role('button',name='Confirmar eliminación').click();await d.wait_for(state='detached');await p.get_by_text('Unidad eliminada del catálogo.',exact=False).wait_for();assert (await api('/api/unidades/contexto?matricula=TESTUSER'))['unidad']['clave']=='B';assert not any(u['clave']=='A' for u in await api('/api/unidades/catalogo'));await p.reload();await p.get_by_role('button',name='Nombres de las unidades',exact=True).click();await p.locator('[data-unit-list]').wait_for();assert await p.locator('[data-unit-list] tr').filter(has_text='Unidad A').count()==0;await p.locator('[data-unit-list] tr').filter(has_text='Unidad C').get_by_role('button',name='Eliminar',exact=True).click();await p.locator('dialog[open]').get_by_role('button',name='Confirmar eliminación').click();await p.get_by_text('Unidad eliminada del catálogo.',exact=False).wait_for();assert not any(u['clave']=='C' for u in await api('/api/unidades/catalogo'));assert not errors,errors;await b.close();print('Eliminar/Cancelar, reemplazo obligatorio, reasignación central, persistencia y diálogo móvil comprobados.')
asyncio.run(main())
